# Regressions for the CPython-protocol pickle implementation.
#
# Two halves.  The oracle half compares every emitted byte against real CPython
# (tests/python/pickle_oracle.py, generated by scripts/gen_pickle_oracle.py) and
# loads CPython's own bytes back.  The named half pins each specific bug found
# while building it -- those are the cases where a plausible-looking
# implementation silently produced wrong DATA rather than an error, which is
# exactly what a wire format must not do.

import sys
import pickle

RESULTS = {}


def _record(key, fn):
    try:
        RESULTS[key] = fn()
    except BaseException as e:
        RESULTS[key] = ("raised", type(e).__name__, str(e))


# ---------------------------------------------------------------------------
# Oracle: byte-exactness against CPython, both directions
# ---------------------------------------------------------------------------
def _oracle():
    oracle = sys.modules['pickle_oracle'].ORACLE
    dump_ok = 0
    load_ok = 0
    problems = []
    for name in sorted(oracle):
        src, protos = oracle[name]
        try:
            value = eval(src)
        except BaseException as e:
            problems.append("eval %s: %s" % (name, e))
            continue
        for proto in sorted(protos):
            expected = protos[proto]
            try:
                got = pickle.dumps(value, proto)
            except BaseException as e:
                problems.append("dump %s p%d: %s: %s" % (name, proto, type(e).__name__, e))
                continue
            if got == expected:
                dump_ok += 1
            else:
                problems.append("dump %s p%d: want %r got %r" % (name, proto, expected, got))
            # Load CPython's OWN bytes, not ours.
            try:
                back = pickle.loads(expected)
                if back == value:
                    load_ok += 1
                else:
                    problems.append("load %s p%d: want %r got %r" % (name, proto, value, back))
            except BaseException as e:
                problems.append("load %s p%d: %s: %s" % (name, proto, type(e).__name__, e))
    return (dump_ok, load_ok, len(oracle), problems)


_record("oracle", _oracle)


# ---------------------------------------------------------------------------
# Round-trip across every protocol
# ---------------------------------------------------------------------------
def _roundtrip_all():
    values = [None, True, False, 0, 1, -1, 2 ** 70, 1.5, '', 'abc', '　x',
              b'', b'abc', bytearray(b'ab'), (), (1,), (1, 2, 3, 4),
              [], [1, [2]], {}, {'a': 1}, {1: True}, set(), {1, 2},
              frozenset({3}), range(0, 10, 2), slice(1, 9, 2)]
    bad = []
    for proto in range(pickle.HIGHEST_PROTOCOL + 1):
        for v in values:
            try:
                back = pickle.loads(pickle.dumps(v, proto))
            except BaseException as e:
                bad.append("p%d %r: %s: %s" % (proto, v, type(e).__name__, e))
                continue
            if back != v or type(back) is not type(v):
                bad.append("p%d %r -> %r (%s)" % (proto, v, back, type(back).__name__))
    return bad


_record("roundtrip_all_protocols", _roundtrip_all)


# ---------------------------------------------------------------------------
# `protocol=` must be HONOURED, not ignored (the old format accepted and
# discarded it, so every protocol produced identical bytes).
# ---------------------------------------------------------------------------
_record("protocol_distinct", lambda: len(set(
    pickle.dumps(True, p) for p in range(pickle.HIGHEST_PROTOCOL + 1))) > 1)
_record("proto2_header", lambda: pickle.dumps(True, 2)[:2] == b'\x80\x02')
_record("bool_p0_is_int01", lambda: pickle.dumps(True, 0) == b'I01\n.')


# ---------------------------------------------------------------------------
# MARK handling.  pop_mark() rebinds the stack and Python binds `.append`
# BEFORE evaluating its argument, so a careless container handler appends to
# the stack it just discarded.  Every protocol 0/1 container goes through it.
# ---------------------------------------------------------------------------
def _mark_containers():
    out = []
    for proto in (0, 1):
        out.append(pickle.loads(pickle.dumps((1, 2), proto)))
        out.append(pickle.loads(pickle.dumps([1, 2], proto)))
        out.append(pickle.loads(pickle.dumps({1: 2}, proto)))
        out.append(pickle.loads(pickle.dumps(frozenset({1}), proto)))
    return out


_record("mark_containers", _mark_containers)


# ---------------------------------------------------------------------------
# Builtin TYPES must be nameable by reference: they are the reconstructors
# REDUCE uses for set/frozenset/bytearray, and Grail's builtins module exposes
# only the FUNCTIONS, so getattr(builtins, 'set') does not resolve.
# ---------------------------------------------------------------------------
_record("set_via_reduce_p2", lambda: pickle.loads(pickle.dumps({1, 2, 3}, 2)))
_record("frozenset_via_reduce_p2", lambda: pickle.loads(pickle.dumps(frozenset({1, 2}), 2)))
_record("bytearray_via_reduce_p2", lambda: pickle.loads(pickle.dumps(bytearray(b'xy'), 2)))
# Protocols 0-2 carry bytes through _codecs.encode; the module must exist.
_record("bytes_p0_names_codecs", lambda: b'_codecs\nencode' in pickle.dumps(b'abc', 0))
_record("bytes_p0_roundtrip", lambda: pickle.loads(pickle.dumps(b'abc', 0)))


# ---------------------------------------------------------------------------
# id() REUSE.  Keying a registry on id() of a transient BoundMethod is unsound:
# the object is collected and the id reused, after which the entry matches
# something unrelated.  That misnamed `iter` as `str`, so iter([]) became
# str([]) and a spent list iterator came back as an iterator over "[]".
# ---------------------------------------------------------------------------
def _spent_iterator():
    it = iter([1, 2])
    list(it)                      # exhaust
    return list(pickle.loads(pickle.dumps(it, 2)))


_record("spent_list_iterator", _spent_iterator)


def _iter_not_misnamed():
    # Churn transient BoundMethods to encourage id reuse before pickling.
    for _ in range(50):
        _ = (iter, str, len, list)
    return list(pickle.loads(pickle.dumps(iter([7, 8]), 2)))


_record("iter_not_misnamed", _iter_not_misnamed)


# ---------------------------------------------------------------------------
# Iterator DIRECTION.  One Grail class backs both iter(list) and
# reversed(list); the direction lives in a state flag, so ignoring it makes
# every forward iterator come back reversed.
# ---------------------------------------------------------------------------
def _iter_directions():
    L = [10, 11, 12, 13]
    fwd = iter(L)
    next(fwd)
    rev = reversed(L)
    next(rev)
    return {
        'fwd_fresh': list(pickle.loads(pickle.dumps(iter(L), 2))),
        'fwd_partial': list(pickle.loads(pickle.dumps(fwd, 2))),
        'rev_fresh': list(pickle.loads(pickle.dumps(reversed(L), 2))),
        'rev_partial': list(pickle.loads(pickle.dumps(rev, 2))),
    }


_record("iter_directions", _iter_directions)


# ---------------------------------------------------------------------------
# BUILD's seek must dispatch on TYPE.  _getstate() layouts differ: a
# list_iterator is (coll, pos, reversed, exhausted) but a range_iterator is
# (start, stop, step, pos) -- so reading slot 2 as a direction flag makes
# range(0, 10, 2) look reversed (step 2 is truthy) and seeks it to exhaustion.
# ---------------------------------------------------------------------------
def _range_iterators():
    r = range(0, 10, 2)
    partial = iter(r)
    next(partial)
    return {
        'fresh': list(pickle.loads(pickle.dumps(iter(r), 2))),
        'partial': list(pickle.loads(pickle.dumps(partial, 2))),
        'plain_step1': list(pickle.loads(pickle.dumps(iter(range(4)), 2))),
    }


_record("range_iterators", _range_iterators)


# ---------------------------------------------------------------------------
# dict VIEW iterators snapshot what is LEFT, and must snapshot the view the
# iterator actually walks -- list(d) yields KEYS, so using it for a values or
# items iterator silently rebuilt the wrong data.
# ---------------------------------------------------------------------------
def _dict_view_iterators():
    d = {1: 'a', 2: 'b', 3: 'c'}
    return {
        'keys': list(pickle.loads(pickle.dumps(iter(d.keys()), 2))),
        'values': list(pickle.loads(pickle.dumps(iter(d.values()), 2))),
        'items': list(pickle.loads(pickle.dumps(iter(d.items()), 2))),
    }


_record("dict_view_iterators", _dict_view_iterators)


# ---------------------------------------------------------------------------
# Container SUBCLASSES keep their type AND instance attributes; the plain
# opcode path would rebuild a base-class instance and drop both.
# ---------------------------------------------------------------------------
class MySet(set):
    pass


class MyFrozenSet(frozenset):
    pass


def _subclass_state():
    s = MySet([1, 2])
    s.tag = 'kept'
    f = MyFrozenSet([3])
    f.tag = 'also'
    back_s = pickle.loads(pickle.dumps(s, 2))
    back_f = pickle.loads(pickle.dumps(f, 2))
    return (type(back_s).__name__, sorted(back_s), getattr(back_s, 'tag', None),
            type(back_f).__name__, sorted(back_f), getattr(back_f, 'tag', None))


_record("subclass_state", _subclass_state)


# ---------------------------------------------------------------------------
# range / slice reduce as (cls, (start, stop, step)); without a dispatch branch
# they fell to the generic path and hit object.__new__(Interval).  Protocols
# 0-2 also rewrite the NAME: builtins.range is emitted as __builtin__.xrange.
# ---------------------------------------------------------------------------
_record("range_roundtrip", lambda: list(pickle.loads(pickle.dumps(range(0, 10, 3), 2))))
_record("slice_roundtrip", lambda: (lambda s: (s.start, s.stop, s.step))(
    pickle.loads(pickle.dumps(slice(1, 9, 2), 2))))
_record("range_p2_names_xrange", lambda: b'xrange' in pickle.dumps(range(3), 2))
_record("range_p3_names_range", lambda: b'\nrange\n' in pickle.dumps(range(3), 3))
_record("range_p0_roundtrip", lambda: list(pickle.loads(pickle.dumps(range(3), 0))))

# range.start/stop/step must be VALUES, not bound methods -- pickle needs the
# ints, and so does any arithmetic a caller does on them.
_record("range_attrs_are_values", lambda: (range(2, 20, 3).start,
                                           range(2, 20, 3).stop,
                                           range(2, 20, 3).step))
_record("range_attr_arithmetic", lambda: range(2, 20, 3).start + 1)


# ---------------------------------------------------------------------------
# Shared references round-trip as ONE object (the memo), and self-reference
# does not run away.
# ---------------------------------------------------------------------------
def _shared_identity():
    inner = [1, 2]
    back = pickle.loads(pickle.dumps((inner, inner), 2))
    back[0].append(3)
    return (back[0] is back[1], back[1])


_record("shared_identity", _shared_identity)


def _recursive_list():
    a = [1]
    a.append(a)
    back = pickle.loads(pickle.dumps(a, 2))
    return (back[0], back[1] is back)


_record("recursive_list", _recursive_list)


# ---------------------------------------------------------------------------
# marshal rides on the same encoder; its supported value types must round-trip
# and unsupported objects must be refused.
# ---------------------------------------------------------------------------
def _marshal():
    import marshal
    vals = [None, True, False, 0, -7, 3.5, 'text', b'bytes', (1, 2), [3], {'k': 'v'}]
    return [marshal.loads(marshal.dumps(v)) == v for v in vals]


_record("marshal_values", _marshal)


def _marshal_rejects():
    import marshal
    return marshal.dumps(MySet([1]))


_record("marshal_rejects_object", _marshal_rejects)


# ---------------------------------------------------------------------------
# Protocol 0 carries bytes as a str through _codecs.encode, so every byte has
# to survive raw-unicode-escape.  Comparing CHARACTERS against control-char
# literals is unreliable here -- chr(128) reprs as empty and matched the
# '\x00' literal, so 0x80 was escaped as \u0000 and b'\x80' came back as
# b'\x00'.  Silent single-byte corruption, at protocol 0 only, which is why it
# needs its own test rather than relying on the ASCII cases.
# ---------------------------------------------------------------------------
def _high_bytes_all_protocols():
    samples = [b'\xff', b'\x80', b'\x00', b'\x1a', b'\\', b'\n', b'\r',
               b'\xffab\x80', bytes(range(256))]
    bad = []
    for proto in range(pickle.HIGHEST_PROTOCOL + 1):
        for b in samples:
            back = pickle.loads(pickle.dumps(b, proto))
            if back != b:
                bad.append("p%d %r -> %r" % (proto, b, back))
    return bad


_record("high_bytes_all_protocols", _high_bytes_all_protocols)


def _high_str_all_protocols():
    samples = ['\x80', '\x00', '\x1a', '\\', '\n', '\u00ff', '\u3000', 'a\\b']
    bad = []
    for proto in range(pickle.HIGHEST_PROTOCOL + 1):
        for t in samples:
            back = pickle.loads(pickle.dumps(t, proto))
            if back != t:
                bad.append("p%d %r -> %r" % (proto, t, back))
    return bad


_record("high_str_all_protocols", _high_str_all_protocols)


class MyBytes(bytes):
    pass


class MyByteArray(bytearray):
    pass


def _bytes_subclass_state():
    a = MyBytes(b'ab')
    a.tag = 'kept'
    c = MyByteArray(b'cd')
    c.tag = 'also'
    back_a = pickle.loads(pickle.dumps(a, 2))
    back_c = pickle.loads(pickle.dumps(c, 2))
    return (type(back_a).__name__, bytes(back_a), getattr(back_a, 'tag', None),
            type(back_c).__name__, bytes(back_c), getattr(back_c, 'tag', None))


_record("bytes_subclass_state", _bytes_subclass_state)
